def solve(a, k):
    lo, hi, ans = 1, ___(a), 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if count(a, mid) >= k:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

static int solve(int[] a, int k) {
